export function applyTransaction(source,edits){
  if(typeof source!=='string'||!Array.isArray(edits))throw Error('invalid transaction');
  const ordered=[];
  for(const edit of edits){
    checkEdit(source,edit);
    const {start,end,after}=edit;
    ordered.push({start,end,after});
  }
  ordered.sort((a,b)=>a.start-b.start||a.end-b.end);
  for(let i=1;i<ordered.length;i++){
    const previous=ordered[i-1], current=ordered[i];
    if(current.start<previous.end ||
      (current.start===previous.end &&
        (previous.start===previous.end||current.start===current.end))){
      throw Error('conflicting edits');
    }
  }
  const parts=[];
  let cursor=0;
  for(const {start,end,after} of ordered){
    parts.push(source.slice(cursor,start),after);
    cursor=end;
  }
  parts.push(source.slice(cursor));
  return {text:parts.join(''),applied:ordered.length};
}

import {readFileSync} from 'node:fs';
import {resolve} from 'node:path';
import {pathToFileURL} from 'node:url';

// Only direct execution reads the JSON file; importing has no CLI side effects.
if(process.argv[1] && import.meta.url===pathToFileURL(resolve(process.argv[1])).href){
  try{
    if(process.argv.length!==3)throw Error('usage: node patch-transaction.js INPUT_JSON_FILE');
    const input=JSON.parse(readFileSync(process.argv[2],'utf8'));
    if(input===null||typeof input!=='object'||Array.isArray(input))throw Error('invalid input');
    const result=applyTransaction(input.source,input.edits);
    process.stdout.write(JSON.stringify(result)+'\n');
  }catch(error){
    process.stderr.write((error instanceof Error?error.message:String(error))+'\n');
    process.exitCode=2;
  }
}

