+import test from 'node:test';
+import assert from 'node:assert/strict';
+import {mkdtempSync, writeFileSync, rmSync} from 'node:fs';
+import {tmpdir} from 'node:os';
+import {join} from 'node:path';
+import {fileURLToPath} from 'node:url';
+import {spawnSync} from 'node:child_process';
+import {applyEdit, applyTransaction} from '../patch-transaction.js';
+
+const edit=(start,end,before,after)=>({start,end,before,after});
+const cli=fileURLToPath(new URL('../patch-transaction.js',import.meta.url));
+
+test('strict validation and original-source preimages',()=>{
+  for(const source of [null,undefined,0,{},new String('abc')]){
+    assert.throws(()=>applyTransaction(source,[]),Error);
+  }
+  for(const edits of [null,undefined,{},'']){
+    assert.throws(()=>applyTransaction('abc',edits),Error);
+  }
+  const invalid=[null,[],undefined,{},'edit',
+    edit(-1,0,'','x'),edit(2,1,'','x'),edit(0,4,'abc','x'),
+    edit(0.5,1,'','x'),edit(0,Infinity,'','x'),
+    edit(0,Number.MAX_SAFE_INTEGER+1,'','x'),
+    edit('0',1,'a','x'),edit(0,'1','a','x'),
+    edit(NaN,1,'a','x'),edit(0,1,null,'x'),edit(0,1,'a',42),
+    edit(0,1,'wrong','x'),edit(1,1,'b','x')];
+  for(const value of invalid){
+    assert.throws(()=>applyTransaction('abc',[value]),Error);
+    assert.throws(()=>applyEdit('abc',value),Error);
+  }
+  assert.throws(()=>applyTransaction('abc',new Array(1)),Error);
+  assert.throws(()=>applyTransaction('abc',[edit(0,1,'a','z'),edit(1,2,'z','x')]),Error);
+});
+
+test('conflicts include empty insertions and both range endpoints in either order',()=>{
+  const range=edit(1,3,'bc','BC');
+  const pairs=[
+    [range,edit(0,2,'ab','')],
+    [range,edit(1,3,'bc','bc')],
+    [edit(0,4,'abcd',''),range],
+    ...[1,2,3].map(pos=>[range,edit(pos,pos,'','')]),
+    [edit(0,0,'',''),edit(0,0,'','x')],
+    [edit(4,4,'',''),edit(4,4,'','')]
+  ];
+  for(const pair of pairs){
+    assert.throws(()=>applyTransaction('abcd',pair),Error);
+    assert.throws(()=>applyTransaction('abcd',[...pair].reverse()),Error);
+  }
+});
+
+test('frozen edits, order independence, no-ops and preservation of UTF-16 and newlines',()=>{
+  const source='A😀B\r\n C\n';
+  const edits=Object.freeze([
+    Object.freeze({...edit(3,4,'B','long'),ignored:true}),
+    Object.freeze(edit(0,0,'','<')),
+    Object.freeze(edit(source.length,source.length,'','>')),
+    Object.freeze(edit(6,7,' ',' '))
+  ]);
+  const expected={text:'<A😀long\r\n C\n>',applied:4};
+  assert.deepEqual(applyTransaction(source,edits),expected);
+  assert.deepEqual(applyTransaction(source,[...edits].reverse()),expected);
+  assert.deepEqual(applyTransaction('😀',[edit(1,2,'\ude00','X')]),{text:'\ud83dX',applied:1});
+  assert.deepEqual(applyTransaction('abcd',[edit(0,2,'ab',''),edit(2,4,'cd','')]),{text:'',applied:2});
+  assert.deepEqual(applyTransaction('',[edit(0,0,'','')]),{text:'',applied:1});
+  for(const text of ['','a','a\r\n','a\n',' \t\r']){
+    assert.deepEqual(applyTransaction(text,[]),{text,applied:0});
+  }
+});
+
+test('CLI success, argument errors, input failures and import isolation',()=>{
+  const dir=mkdtempSync(join(tmpdir(),'patch-transaction-'));
+  const file=join(dir,'input.json');
+  const run=args=>spawnSync(process.execPath,[cli,...args],{encoding:'utf8'});
+  const failure=args=>{
+    const result=run(args);
+    assert.ifError(result.error);
+    assert.equal(result.status,2);
+    assert.equal(result.stdout,'');
+    assert.ok(result.stderr.trim().length>0);
+  };
+  try{
+    writeFileSync(file,JSON.stringify({source:'a😀\r\n',edits:[edit(0,1,'a','Z')],extra:1}));
+    const success=run([file]);
+    assert.ifError(success.error);
+    assert.equal(success.status,0);
+    assert.equal(success.stdout,JSON.stringify({text:'Z😀\r\n',applied:1})+'\n');
+    assert.equal(success.stderr,'');
+    failure([]);
+    failure([file,file]);
+    failure([join(dir,'missing.json')]);
+    failure([dir]);
+    for(const input of ['{','null','[]','{}',
+      JSON.stringify({source:3,edits:[]}),
+      JSON.stringify({source:'a',edits:[edit(0,1,'b','x')]}),
+      JSON.stringify({source:'a',edits:[edit(0,0,'',''),edit(0,0,'','x')]})]){
+      writeFileSync(file,input);
+      failure([file]);
+    }
+    const imported=spawnSync(process.execPath,['--input-type=module','-e',
+      `await import(${JSON.stringify(new URL('../patch-transaction.js',import.meta.url).href)})`],{encoding:'utf8'});
+    assert.ifError(imported.error);
+    assert.equal(imported.status,0);
+    assert.equal(imported.stdout,'');
+    assert.equal(imported.stderr,'');
+  }finally{
+    rmSync(dir,{recursive:true,force:true});
+  }
+});
